-- Government news source registry: columns + unique-title index + seed articles
-- Mirrors lib/gov-sources.ts and supabase/functions/fetch-news.

ALTER TABLE public.news_articles ADD COLUMN IF NOT EXISTS agency_type text;
ALTER TABLE public.news_articles ADD COLUMN IF NOT EXISTS sector text;
ALTER TABLE public.news_articles ADD COLUMN IF NOT EXISTS source_key text;

CREATE UNIQUE INDEX IF NOT EXISTS idx_news_articles_title_unique
  ON public.news_articles (title);

CREATE INDEX IF NOT EXISTS idx_news_articles_source_key
  ON public.news_articles (source_key);

INSERT INTO public.news_articles
  (title, title_en, summary, summary_en, category, region, source, source_key, agency_type, sector, published_at, source_type)
VALUES
  ('2026 Tarımsal Destekleme Ödemeleri İçin Başvurular Başladı', '2026 Agricultural Support Payment Applications Open',
   'Tarım ve Orman Bakanlığı, 2026 yılı tarımsal destekleme ödemeleri için başvuruların 1 Kasım itibarıyla başladığını duyurdu. Çiftçiler e-Devlet üzerinden veya il müdürlüklerine başvuru yapabilir.',
   'The Ministry of Agriculture and Forestry announced that applications for 2026 agricultural support payments have opened as of November 1. Farmers can apply via e-Government or provincial directorates.',
   'policy', 'all', 'T.C. Tarım ve Orman Bakanlığı', 'tarimorman', 'Central Ministry', 'Central Policy & Extension', '2026-10-22T09:00:00Z', 'rss'),
  ('Bakanlık''tan Kırsal Kalkınma Yeni Strateji Belgesi Yayımlandı', 'New Rural Development Strategy Document Published by the Ministry',
   '2026-2030 dönemini kapsayan Ulusal Kırsal Kalkınma Strateji Belgesi Resmî Gazete''de yayımlandı. Belge kırsal istihdam, dijital tarım ve kadın girişimciliğe odaklanıyor.',
   'The National Rural Development Strategy Document covering 2026-2030 was published in the Official Gazette. The document focuses on rural employment, digital agriculture, and women entrepreneurs.',
   'policy', 'all', 'T.C. Tarım ve Orman Bakanlığı', 'tarimorman', 'Central Ministry', 'Central Policy & Extension', '2026-10-18T14:30:00Z', 'rss'),
  ('Tarım TV Yeni Yayın Dönemi: Akıllı Tarım Uygulamaları Serisi', 'Tarım TV New Season: Smart Agriculture Applications Series',
   'Tarım TV, yeni yayın döneminde akıllı tarım uygulamaları, hassas tarım teknolojileri ve dijital çiftlik yönetimi konularında eğitim serisi başlatıyor.',
   'Tarım TV launches an educational series on smart agriculture applications, precision farming technologies, and digital farm management for the new broadcast season.',
   'general', 'all', 'Tarım TV', 'tarimtv', 'Central Ministry', 'Central Policy & Extension', '2026-10-15T10:00:00Z', 'rss'),
  ('TMO 2026/2027 Hububat Alım Fiyatları Açıklandı', 'TMO 2026/2027 Cereal Purchase Prices Announced',
   'Toprak Mahsulleri Ofisi, 2026/2027 sezonu hububat alım fiyatlarını açıkladı. Kırmızı sert buğday ton başına 13.250 TL, beyaz sert buğday 13.000 TL olarak belirlendi.',
   'The Turkish Grain Board announced 2026/2027 season cereal purchase prices. Red hard wheat is set at 13,250 TL per ton, white hard wheat at 13,000 TL per ton.',
   'market', 'İç Anadolu', 'Toprak Mahsulleri Ofisi (TMO)', 'tmo', 'State-Owned Enterprise', 'Grains & Cereals', '2026-10-21T11:00:00Z', 'rss'),
  ('TMO Müdahale Alımları: Mısır Stokları Güvenli Seviyede', 'TMO Intervention Purchases: Corn Stocks at Safe Levels',
   'TMO, iç talebi karşılamak üzere mısır müdahale alımlarını sürdürüyor. Mevcut stokların 2.8 milyon ton ile güvenli seviyede olduğu bildirildi.',
   'TMO continues corn intervention purchases to meet domestic demand. Current stocks are reported at a safe level of 2.8 million tons.',
   'market', 'Marmara', 'Toprak Mahsulleri Ofisi (TMO)', 'tmo', 'State-Owned Enterprise', 'Grains & Cereals', '2026-10-19T08:15:00Z', 'rss'),
  ('ESK Et Fiyatlarındaki Düşüşün Ardından Müdahale Alımı Kararı Aldı', 'ESK Decides on Intervention Purchases After Meat Price Decline',
   'Et ve Süt Kurumu, kırmızı et fiyatlarındaki düşüşü dengelemek amacıyla müdahale alımlarına başlayacağını açıkladı. Haftalık 5.000 ton sığır eti alımı planlanıyor.',
   'The Meat and Milk Board announced it will begin intervention purchases to stabilize red meat prices following a decline. A weekly purchase of 5,000 tons of beef is planned.',
   'market', 'all', 'Et ve Süt Kurumu (ESK)', 'esk', 'State-Owned Enterprise', 'Livestock & Dairy', '2026-10-22T15:00:00Z', 'rss'),
  ('ESK Süt Tozu İhracatında Yeni Rekora Doğru', 'ESK Approaching New Record in Milk Powder Exports',
   'Et ve Süt Kurumu destekleriyle süt tozu üretimi 180.000 tona yaklaştı. İhracat gelirinin 950 milyon dolara ulaşması bekleniyor.',
   'With Meat and Milk Board support, milk powder production is approaching 180,000 tons. Export revenue is expected to reach 950 million dollars.',
   'market', 'all', 'Et ve Süt Kurumu (ESK)', 'esk', 'State-Owned Enterprise', 'Livestock & Dairy', '2026-10-16T12:00:00Z', 'rss'),
  ('TİGEM 2026 Tohumluk Dağıtım Programı Yayında', 'TİGEM 2026 Seed Distribution Program Published',
   'Tarım İşletmeleri Genel Müdürlüğü, 2026 yılı sertifikalı tohumluk dağıtım programını yayımladı. Buğday, arpa ve ayçiçeği tohumları 15 Kasım''dan itibaren dağıtılacak.',
   'The General Directorate of Agricultural Enterprises published its 2026 certified seed distribution program. Wheat, barley, and sunflower seeds will be distributed starting November 15.',
   'policy', 'İç Anadolu', 'TİGEM', 'tigem', 'State-Owned Enterprise', 'Seeds & State Farming', '2026-10-20T09:30:00Z', 'rss'),
  ('TİGEM Damızlık Sığır Satış İhalesi Sonuçlandı', 'TİGEM Breeding Cattle Sale Auction Concluded',
   'TİGEM''in Ceylanpınar Tarım İşletmesi''ndeki damızlık Holstein satış ihalesi tamamlandı. Ortalama satış fiyatı başına 68.500 TL olarak gerçekleşti.',
   'TİGEM''s breeding Holstein sale auction at Ceylanpınar Agricultural Enterprise was completed. The average sale price was 68,500 TL per head.',
   'market', 'Güneydoğu Anadolu', 'TİGEM', 'tigem', 'State-Owned Enterprise', 'Seeds & State Farming', '2026-10-14T16:00:00Z', 'rss'),
  ('TAGEM Buğday Pas Hastalığı Erken Uyarı Sistemi Devrede', 'TAGEM Wheat Rust Disease Early Warning System Operational',
   'Tarımsal Araştırmalar Genel Müdürlüğü, İç Anadolu''da buğday pas hastalığı için yeni erken uyarı sistemini devreye aldı. Sistem tarla sensörleri ve uydu verisi kullanıyor.',
   'The General Directorate of Agricultural Research activated a new early warning system for wheat rust disease in Central Anatolia. The system uses field sensors and satellite data.',
   'policy', 'İç Anadolu', 'TAGEM', 'tagem', 'Research & Extension', 'Research & Disease Control', '2026-10-21T13:45:00Z', 'rss'),
  ('TAGEM Yeni Domates Çeşidi: "Anatolia F1" Tescil Edildi', 'TAGEM New Tomato Variety: "Anatolia F1" Registered',
   'TAGEM araştırmacıları, kuraklığa dayanıklı ve yüksek verimli "Anatolia F1" domates çeşidini tescilledi. Çeşit dekara 8-10 ton verim potansiyeline sahip.',
   'TAGEM researchers registered the drought-resistant, high-yield "Anatolia F1" tomato variety. The variety has a yield potential of 8-10 tons per decare.',
   'general', 'Akdeniz', 'TAGEM', 'tagem', 'Research & Extension', 'Research & Disease Control', '2026-10-12T11:20:00Z', 'rss'),
  ('DSİ 2026 Sulama Sezonu Açılış Tarihi Açıklandı', 'DSİ 2026 Irrigation Season Opening Date Announced',
   'Devlet Su İşleri, 2026 sulama sezonunun 15 Nisan''da açılacağını duyurdu. Konya Ovası, Harran Ovası ve GAP sulama şebekeleri için hazırlıklar sürüyor.',
   'The State Hydraulic Works announced that the 2026 irrigation season will open on April 15. Preparations continue for Konya Plain, Harran Plain, and GAP irrigation networks.',
   'policy', 'İç Anadolu', 'Devlet Su İşleri (DSİ)', 'dsi', 'Water & Infrastructure', 'Irrigation & Water', '2026-10-20T10:00:00Z', 'rss'),
  ('DSİ''den Sulamada Tasarruf: Damla Sulama Hibeleri Genişletildi', 'DSİ Water Savings: Drip Irrigation Grants Expanded',
   'Devlet Su İşleri, damla sulama sistemleri için hibe oranını %60''tan %75''e çıkardı. Hedef yıllık 2 milyar m³ su tasarrufu sağlamak.',
   'The State Hydraulic Works raised the grant rate for drip irrigation systems from 60% to 75%. The target is to save 2 billion cubic meters of water annually.',
   'policy', 'all', 'Devlet Su İşleri (DSİ)', 'dsi', 'Water & Infrastructure', 'Irrigation & Water', '2026-10-17T14:00:00Z', 'rss'),
  ('TKDK 13. IPARD Çağrısı: 4.2 Milyar TL Hibe Duyuruldu', 'TKDK 13th IPARD Call: 4.2 Billion TL Grant Announced',
   'Tarımsal Kalkınma Kooperatifi, 13. IPARD çağrısı kapsamında 4.2 milyar TL hibe desteği duyurdu. Süt üretimi, meyve işleme ve kırsal turizm yatırımları desteklenecek.',
   'The Agricultural and Rural Development Support Institution announced 4.2 billion TL in grant support under the 13th IPARD call. Milk production, fruit processing, and rural tourism investments will be supported.',
   'policy', 'all', 'TKDK', 'tkdk', 'Grants & Financing', 'Grants & EU IPARD', '2026-10-22T10:30:00Z', 'rss'),
  ('TKDK IPARD Başvuru Eğitimleri Kasımda Başlıyor', 'TKDK IPARD Application Trainings Start in November',
   'TKDK, 13. çağrı dönemi için ücretsiz başvuru eğitim seminerlerini 81 ilde başlatıyor. Eğitimlerde proje hazırlama, bütçe planlama ve raporlama konuları işlenecek.',
   'TKDK is launching free application training seminars in all 81 provinces for the 13th call period. Topics include project preparation, budget planning, and reporting.',
   'general', 'all', 'TKDK', 'tkdk', 'Grants & Financing', 'Grants & EU IPARD', '2026-10-18T09:00:00Z', 'rss'),
  ('TARSİM 2026 Kuraklık Tazminat Ödemeleri Devam Ediyor', 'TARSİM 2026 Drought Compensation Payments Continue',
   'Tarım Sigortaları Havuzu, 2026 yılı kuraklık hasar ödemelerini sürdürüyor. Şu ana kadar 38 ilde 12.500 çiftçiye 420 milyon TL ödeme yapıldı.',
   'The Agricultural Insurance Pool continues 2026 drought damage payments. To date, 420 million TL has been paid to 12,500 farmers in 38 provinces.',
   'policy', 'İç Anadolu', 'TARSİM', 'tarsim', 'Insurance & Risk', 'Risk & Disaster Relief', '2026-10-21T16:00:00Z', 'rss'),
  ('TARSİM Poliçe Kapsamı Dolu Yağışı ve Sel İçin Genişletildi', 'TARSİM Policy Coverage Expanded for Hail and Flood',
   'TARSİM, 2026 yılı poliçelerinde dolu yağışı ve sel hasarını da kapsayan yeni sigorta paketi tanıttı. Prim desteği %50 ile %65 arasında değişiyor.',
   'TARSİM introduced a new insurance package covering hail and flood damage in 2026 policies. Premium support ranges from 50% to 65%.',
   'policy', 'all', 'TARSİM', 'tarsim', 'Insurance & Risk', 'Risk & Disaster Relief', '2026-10-13T11:00:00Z', 'rss'),
  ('ÇAYKUR 2026 Çay Alım Fiyatları Yükseltildi', 'ÇAYKUR 2026 Tea Purchase Prices Increased',
   'Çay İşletmeleri Genel Müdürlüğü, 2026 yılı yaş çay alım fiyatını kilogramda 14.50 TL''ye yükseltti. Bu, geçen yıla göre %18 oranında artış anlamına geliyor.',
   'The General Directorate of Tea Enterprises raised the 2026 fresh tea purchase price to 14.50 TL per kilogram. This represents an 18% increase over last year.',
   'market', 'Karadeniz', 'ÇAYKUR', 'caykur', 'State-Owned Enterprise', 'Tea & Industrial Crops', '2026-10-19T10:00:00Z', 'rss'),
  ('ÇAYKUR Yeni Çay İşleme Tesisi Rize''de Açıldı', 'ÇAYKUR New Tea Processing Facility Opened in Rize',
   'ÇAYKUR''un Rize''de kurduğu yeni çay işleme tesisi açıldı. Günlük 250 ton yaş çay işleme kapasitesine sahip tesis, bölgede 400 kişiye istihdam sağlıyor.',
   'ÇAYKUR''s new tea processing facility in Rize has opened. The facility has a daily processing capacity of 250 tons of fresh tea and provides employment for 400 people in the region.',
   'general', 'Karadeniz', 'ÇAYKUR', 'caykur', 'State-Owned Enterprise', 'Tea & Industrial Crops', '2026-10-11T14:30:00Z', 'rss'),
  ('TÜRKŞEKER 2026 Şeker Pancarı Alım Fiyatı: 2.150 TL/Ton', 'TÜRKŞEKER 2026 Sugar Beet Purchase Price: 2,150 TL/Ton',
   'Türkiye Şeker Fabrikaları, 2026 kampanya dönemi şeker pancarı alım fiyatını ton başına 2.150 TL olarak açıkladı. Geçen yıla göre %22 artış.',
   'Turkish Sugar Factories announced the 2026 campaign sugar beet purchase price at 2,150 TL per ton. A 22% increase over last year.',
   'market', 'İç Anadolu', 'TÜRKŞEKER', 'turkseker', 'State-Owned Enterprise', 'Sugar & Sweeteners', '2026-10-20T15:00:00Z', 'rss'),
  ('TÜRKŞEKER Pancar Kampanyası 20 Ekim''de Başladı', 'TÜRKŞEKER Beet Campaign Started on October 20',
   'TÜRKŞEKER''in 2026-2027 şeker pancarı kampanyası 20 Ekim''de başladı. 25 fabrikanın tamamı kesintisiz üretim için hazır duruma getirildi.',
   'TÜRKŞEKER''s 2026-2027 sugar beet campaign started on October 20. All 25 factories were prepared for continuous production.',
   'general', 'all', 'TÜRKŞEKER', 'turkseker', 'State-Owned Enterprise', 'Sugar & Sweeteners', '2026-10-20T06:00:00Z', 'rss'),
  ('TÜİK 2026 Üçüncü Çeyrek Tarımsal GSYH: %3.8 Büyüme', 'TÜİK Q3 2026 Agricultural GDP: 3.8% Growth',
   'Türkiye İstatistik Kurumu verilerine göre tarım sektörü 2026 üçüncü çeyrekte %3.8 büyüdü. Hayvancılık alt sektörü %6.2 ile en yüksek katkıyı sağladı.',
   'According to Turkish Statistical Institute data, the agricultural sector grew 3.8% in Q3 2026. The livestock sub-sector contributed the most at 6.2%.',
   'market', 'all', 'TÜİK', 'tuik', 'Statistics & Legislation', 'Statistics', '2026-10-22T10:00:00Z', 'rss'),
  ('TÜİK Gıda Enflasyonu Eylülde %1.2 Geriledi', 'TÜİK Food Inflation Declined 1.2% in September',
   'TÜİK verilerine göre eylül ayında gıda ve alkolsüz içecek fiyatları aylık %1.2 düştü. Meyve-sebze grubunda fiyat düşüşü belirgin oldu.',
   'According to TÜİK data, food and non-alcoholic beverage prices fell 1.2% monthly in September. Price declines were notable in the fruit-vegetable group.',
   'market', 'all', 'TÜİK', 'tuik', 'Statistics & Legislation', 'Statistics', '2026-10-17T09:00:00Z', 'rss'),
  ('Resmî Gazete: Tarımsal Destekleme Kanununda Değişiklik Yapıldı', 'Official Gazette: Agricultural Support Law Amended',
   '5488 sayılı Tarım Kanununda değişiklik yapan tebliğ Resmî Gazete''de yayımlandı. Değişiklik dijital tarım uygulamaları için yeni destek kalemi ekliyor.',
   'A directive amending Agricultural Law No. 5488 was published in the Official Gazette. The amendment adds a new support line for digital agriculture applications.',
   'policy', 'all', 'Resmî Gazete', 'resmigazete', 'Statistics & Legislation', 'Legislation', '2026-10-22T08:00:00Z', 'rss'),
  ('Resmî Gazete: Organik Tarım Tebliği Yürürlüğe Girdi', 'Official Gazette: Organic Agriculture Directive Entered into Force',
   'Organik Tarımın Esasları ve Uygulanmasına İlişkin Tebliğ Resmî Gazete''de yayımlanarak yürürlüğe girdi. Tebliğ sertifikasyon süreçlerini kolaylaştırıyor.',
   'The Directive on the Principles and Implementation of Organic Agriculture was published in the Official Gazette and entered into force. The directive simplifies certification processes.',
   'policy', 'all', 'Resmî Gazete', 'resmigazete', 'Statistics & Legislation', 'Legislation', '2026-10-14T08:30:00Z', 'rss'),
  ('Tarım Kredi''den Gübre Fiyatlarında %15 İndirim', 'Agricultural Credit Cooperative Announces 15% Fertilizer Price Cut',
   'Tarım Kredi Kooperatifleri, gübre fiyatlarında ortalama %15 indirim yaptığını açıkladı. İndirim DAP, üre ve ASN gübrelerini kapsıyor.',
   'Agricultural Credit Cooperatives announced an average 15% price reduction on fertilizers. The reduction covers DAP, urea, and ASN fertilizers.',
   'market', 'all', 'Tarım Kredi Kooperatifleri', 'tarimkredi', 'Producer Cooperative', 'Producer Credit & Inputs', '2026-10-21T09:00:00Z', 'rss'),
  ('Tarım Kredi Düşük Faizli Çiftçi Kredisi Paketi Yayında', 'Agricultural Credit Launches Low-Interest Farmer Credit Package',
   'Tarım Kredi Kooperatifleri, ekim dönemi için düşük faizli çiftçi kredisi paketi yayınladı. 100.000 TL''ye kadar krediler aylık %0.89 faizle sağlanıyor.',
   'Agricultural Credit Cooperatives released a low-interest farmer credit package for the planting season. Credits up to 100,000 TL are offered at 0.89% monthly interest.',
   'policy', 'all', 'Tarım Kredi Kooperatifleri', 'tarimkredi', 'Producer Cooperative', 'Producer Credit & Inputs', '2026-10-16T10:00:00Z', 'rss'),
  ('AA: Türkiye''nin Buğday Üretimi 2026''da Rekor Bekleniyor', 'AA: Turkey''s Wheat Production Expected to Hit Record in 2026',
   'Anadolu Ajansı''nın tarım muhabirlerinin derlediği bilgilere göre, 2026 buğday üretiminin 22.5 milyon tona ulaşarak rekor kırması bekleniyor.',
   'According to information compiled by Anadolu Agency''s agriculture correspondents, 2026 wheat production is expected to reach 22.5 million tons, a new record.',
   'market', 'all', 'Anadolu Ajansı', 'aa', 'Wire Service', 'Wire Coverage', '2026-10-22T12:00:00Z', 'rss'),
  ('AA: İhracatçılar Antep Fıstığı Pazarında Yeni Pazarlar Arıyor', 'AA: Exporters Seek New Markets for Pistachios',
   'Anadolu Ajansı''na göre, Gaziantepli Antep fıstığı ihracatçıları Avrupa ve Uzakdoğu pazarlarına açılıyor. 2026 ihracat hedefi 220 milyon dolar.',
   'According to Anadolu Agency, pistachio exporters from Gaziantep are expanding into European and Far Eastern markets. The 2026 export target is 220 million dollars.',
   'general', 'Güneydoğu Anadolu', 'Anadolu Ajansı', 'aa', 'Wire Service', 'Wire Coverage', '2026-10-18T13:00:00Z', 'rss')
